/**
 * Mid-game item choices in public matches by rank bracket and position
 * (data/bracket-items.json from STRATZ, regenerated by
 * scripts/coach-bracket-items.mjs). Pure lookups: the engine never fetches.
 *
 * Every number carries its sample, its role scope (exact Pos 1–5 when known
 * with enough games, else pooled core Pos 1–3 or support Pos 4–5 — never all
 * positions mixed together) and the STRATZ attribution.
 *
 * Unknown is not false: an unbuilt snapshot, an unknown bracket or role, an
 * unplaced game release, or a cell with fewer than BRACKET_ITEMS_MIN_GAMES
 * returns `result: null` with a `gaps` entry explaining why.
 */
import { createRequire } from 'node:module';
import { ALWAYS_KEY_ITEMS, KEY_ITEM_MIN_COST } from './knowledge.js';
import { isBigItemIn } from '../agent/patchData.js';
import { releaseIsPlaced } from '../agent/proItems.js';

const DATA = createRequire(import.meta.url)('./data/bracket-items.json');

export const BRACKET_ITEMS_MIN_GAMES = 50;
export const BRACKET_ITEMS_MIN_BUYS = 25;

export const BRACKET_ITEMS_SOURCE = Object.freeze({
  source: DATA.source,
  attribution: DATA.attribution,
  window: DATA.window,
  patch: DATA.patch,
  weeks: DATA.weeks,
  fetched: DATA.fetched,
});

export const ROLE_GROUP_LABEL = Object.freeze({
  position_1: { en: 'Pos 1 (carry)', zh: '1 号位（一号位核心）', ru: 'Поз. 1 (керри)' },
  position_2: { en: 'Pos 2 (mid)', zh: '2 号位（中单）', ru: 'Поз. 2 (мид)' },
  position_3: { en: 'Pos 3 (offlane)', zh: '3 号位（劣势路）', ru: 'Поз. 3 (оффлейн)' },
  position_4: { en: 'Pos 4 (soft support)', zh: '4 号位（游走辅助）', ru: 'Поз. 4 (четвёрка)' },
  position_5: { en: 'Pos 5 (hard support)', zh: '5 号位（五号位辅助）', ru: 'Поз. 5 (пятёрка)' },
  core: { en: 'core (Pos 1–3)', zh: '核心（1–3 号位）', ru: 'кор (поз. 1–3)' },
  support: { en: 'support (Pos 4–5)', zh: '辅助（4–5 号位）', ru: 'саппорт (поз. 4–5)' },
});

const r2 = (n) => Math.round(n * 100) / 100;

/**
 * Sum disjoint position cells (`1..3` or `4..5`) when pre-pooled `core` /
 * `support` is not stored on a custom fixture. Median minute is omitted when
 * summing cells without the underlying per-minute histogram (no guessed median).
 */
function poolPositions(byRole, positions) {
  let games = 0;
  let wins = 0;
  const items = new Map();
  for (const p of positions) {
    const cell = byRole?.[String(p)];
    if (!cell || !Number.isFinite(cell.games) || cell.games <= 0) continue;
    games += cell.games;
    wins += cell.wins ?? 0;
    for (const [key, buys, itemWins] of cell.items ?? []) {
      const prev = items.get(key) ?? [0, 0];
      items.set(key, [prev[0] + buys, prev[1] + itemWins]);
    }
  }
  if (!games) return null;
  return {
    games,
    wins,
    items: [...items.entries()]
      .map(([k, [b, w]]) => [k, b, w, null])
      .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])),
  };
}

/**
 * Look up public mid-game items for `heroId` in `{ bracket, pos, kind }` for a
 * game on release `pd` (`patchForGame`).
 *
 * @param {number} heroId
 * @param {{ bracket?: string | null, pos?: number | null, kind?: 'core' | 'support' | null, hasMatch?: boolean }} scope
 * @param {any} pd  from `patchForGame`
 * @param {any} [data]  snapshot override for tests
 */
export function bracketItemsFor(heroId, { bracket = null, pos = null, kind = null, hasMatch = true } = {}, pd = null, data = DATA) {
  if (!hasMatch) {
    return { result: null, gaps: [{ topic: 'rank_bracket_items', reason: 'no_match_data_for_this_game' }] };
  }
  if (!bracket) {
    return { result: null, gaps: [{ topic: 'rank_bracket_items', reason: 'bracket_unknown_for_this_game' }] };
  }
  if (!releaseIsPlaced(pd)) {
    return { result: null, gaps: [{ topic: 'rank_bracket_items', reason: `release_of_this_game_not_known_${pd?.reason ?? 'unknown'}` }] };
  }
  if (!data?.patch || !data?.heroes) {
    return { result: null, gaps: [{ topic: 'rank_bracket_items', reason: 'public_bracket_item_snapshot_not_built_yet' }] };
  }

  const validPos = Number.isInteger(pos) && pos >= 1 && pos <= 5 ? pos : null;
  const inferredKind = kind === 'core' || kind === 'support' ? kind : (validPos != null ? (validPos <= 3 ? 'core' : 'support') : null);
  if (validPos == null && !inferredKind) {
    return { result: null, gaps: [{ topic: 'rank_bracket_items', reason: 'role_unknown_for_this_game' }] };
  }

  const byRole = data.heroes?.[bracket]?.[String(heroId)];
  if (!byRole) {
    return { result: null, gaps: [{ topic: 'rank_bracket_items', reason: 'too_few_public_games_in_this_bracket_and_role' }] };
  }

  const gaps = [];
  let row = null;
  let roleGroup = null;
  let usedPos = null;

  if (validPos != null) {
    const exact = byRole[String(validPos)];
    if (exact && exact.games >= BRACKET_ITEMS_MIN_GAMES) {
      row = exact;
      roleGroup = `position_${validPos}`;
      usedPos = validPos;
    } else if (inferredKind) {
      const fallback = byRole[inferredKind] ?? poolPositions(byRole, inferredKind === 'core' ? [1, 2, 3] : [4, 5]);
      if (fallback && fallback.games >= BRACKET_ITEMS_MIN_GAMES) {
        row = fallback;
        roleGroup = inferredKind;
        gaps.push({ topic: 'rank_bracket_items_position', reason: `too_few_public_games_in_position_${validPos}_using_${inferredKind}` });
      }
    }
  } else if (inferredKind) {
    const pooled = byRole[inferredKind] ?? poolPositions(byRole, inferredKind === 'core' ? [1, 2, 3] : [4, 5]);
    if (pooled && pooled.games >= BRACKET_ITEMS_MIN_GAMES) {
      row = pooled;
      roleGroup = inferredKind;
      gaps.push({ topic: 'rank_bracket_items_position', reason: `exact_position_unknown_using_${inferredKind}` });
    }
  }

  if (!row || row.games < BRACKET_ITEMS_MIN_GAMES) {
    return { result: null, gaps: [{ topic: 'rank_bracket_items', reason: 'too_few_public_games_in_this_bracket_and_role' }] };
  }

  // Only items that existed and counted as key/big items in this game's own release.
  const items = (row.items ?? [])
    .filter(([k, buys]) => buys >= BRACKET_ITEMS_MIN_BUYS && pd.has(k) && isBigItemIn(pd, k, { minCost: KEY_ITEM_MIN_COST, always: ALWAYS_KEY_ITEMS }))
    .map(([k, buys, wins, medianMin]) => ({
      item: k,
      purchases: buys,
      share_of_public_games: r2(Math.min(1, buys / row.games)),
      win_rate: r2(wins / buys),
      ...(Number.isInteger(medianMin) ? { median_minute: medianMin } : {}),
    }));

  if (!items.length) {
    return { result: null, gaps: [{ topic: 'rank_bracket_items', reason: 'too_few_mid_game_item_purchases_in_this_bracket_and_role' }] };
  }

  const fromAnotherPatch = Boolean(pd?.major && data.patch !== pd.major);
  if (fromAnotherPatch) {
    gaps.push({ topic: 'rank_bracket_items_patch', reason: `measured_in_${data.patch}_for_a_${pd.name}_game` });
  }

  return {
    result: {
      bracket,
      role_group: roleGroup,
      ...(usedPos != null ? { position: usedPos } : {}),
      public_games: row.games,
      win_rate: r2(row.wins / row.games),
      patch: data.patch,
      weeks: data.weeks,
      ...(fromAnotherPatch ? { from_another_patch: true } : {}),
      window: data.window ?? 'finished between 10:00 and 24:59',
      source: 'STRATZ',
      attribution: data.attribution ?? { en: 'Data: STRATZ', url: 'https://stratz.com' },
      items,
    },
    gaps,
  };
}
